static int retention_init(const struct device *dev)
{
	const struct retention_config *config = dev->config;
	int rc;

	if (!device_is_ready(config->retained_mem_dev)) {
		LOG_ERR("Retained memory device %s is not ready", config->retained_mem_dev->name);
		return -ENODEV;
	}

#ifdef CONFIG_RETENTION_MUTEXES
	struct retention_data *data = dev->data;
	k_mutex_init(&data->mutex);
#endif

	return 0;
}

#ifdef CONFIG_RETENTION_MUTEXES
#define RETENTION_LOCK(dev) k_mutex_lock(&((struct retention_data *)dev->data)->mutex, K_FOREVER)
#define RETENTION_UNLOCK(dev) k_mutex_unlock(&((struct retention_data *)dev->data)->mutex)
#else
#define RETENTION_LOCK(dev)
#define RETENTION_UNLOCK(dev)
#endif

static ssize_t retention_zephyr_size(const struct device *dev)
{
	const struct retention_config *config = dev->config;
	return config->size;
}

static int retention_zephyr_read(const struct device *dev, off_t offset, uint8_t *buffer, size_t size)
{
	const struct retention_config *config = dev->config;
	int rc;

	if ((offset + size) > config->size) {
		return -EINVAL;
	}

	RETENTION_LOCK(dev);
	rc = retained_mem_read(config->retained_mem_dev, config->offset + offset, buffer, size);
	RETENTION_UNLOCK(dev);

	return rc;
}

static int retention_zephyr_write(const struct device *dev, off_t offset, const uint8_t *buffer, size_t size)
{
	const struct retention_config *config = dev->config;
	int rc;

	if ((offset + size) > config->size) {
		return -EINVAL;
	}

	RETENTION_LOCK(dev);
	rc = retained_mem_write(config->retained_mem_dev, config->offset + offset, buffer, size);
	RETENTION_UNLOCK(dev);

	return rc;
}

static int retention_zephyr_clear(const struct device *dev)
{
	const struct retention_config *config = dev->config;
	int rc = 0;
	uint8_t zero_buffer[CONFIG_RETENTION_BUFFER_SIZE];

	memset(zero_buffer, 0, sizeof(zero_buffer));

	RETENTION_LOCK(dev);
	for (size_t i = 0; i < config->size; i += sizeof(zero_buffer)) {
		size_t write_size = MIN(sizeof(zero_buffer), config->size - i);
		rc = retained_mem_write(config->retained_mem_dev, config->offset + i, zero_buffer, write_size);
		if (rc != 0) {
			break;
		}
	}
	RETENTION_UNLOCK(dev);

	return rc;
}

