#define DT_DRV_COMPAT zephyr_retention

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/retained_mem.h>
#include <zephyr/retention/retention.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/byteorder.h>
#include <zephyr/sys/crc.h>

LOG_MODULE_REGISTER(retention, CONFIG_RETENTION_LOG_LEVEL);

/** Retention device private data. */
struct retention_data {
#ifdef CONFIG_RETENTION_MUTEXES
	struct k_mutex mutex;
#endif
};

/** Retention device configuration. */
struct retention_config {
	const struct device *retained_mem_dev;
	off_t offset;
	size_t size;
	bool has_prefix;
	uint16_t prefix_val;
};

/** Retention driver API. */
struct retention_driver_api {
	ssize_t (*size)(const struct device *dev);
	int (*is_valid)(const struct device *dev);
	int (*read)(const struct device *dev, off_t offset, uint8_t *buffer, size_t size);
	int (*write)(const struct device *dev, off_t offset, const uint8_t *buffer, size_t size);
	int (*clear)(const struct device *dev);
};

static int retention_lock(const struct device *dev)
{
#ifdef CONFIG_RETENTION_MUTEXES
	struct retention_data *data = dev->data;

	return k_mutex_lock(&data->mutex, K_FOREVER);
#else
	return 0;
#endif
}

static int retention_unlock(const struct device *dev)
{
#ifdef CONFIG_RETENTION_MUTEXES
	struct retention_data *data = dev->data;

	k_mutex_unlock(&data->mutex);
#endif
	return 0;
}

static int retention_init(const struct device *dev)
{
#ifdef CONFIG_RETENTION_MUTEXES
	struct retention_data *data = dev->data;

	k_mutex_init(&data->mutex);
#endif
	return 0;
}

static ssize_t retention_size_impl(const struct device *dev)
{
	const struct retention_config *config = dev->config;
	size_t usable_size = config->size;

	if (config->has_prefix) {
		usable_size -= sizeof(uint16_t);
	}

	return usable_size;
}

static int retention_is_valid_impl(const struct device *dev)
{
	const struct retention_config *config = dev->config;
	int rc;

	if (!config->has_prefix) {
		return -ENOTSUP;
	}

	rc = retention_lock(dev);
	if (rc != 0) {
		return rc;
	}

	uint16_t stored_prefix;
	rc = retained_mem_read(config->retained_mem_dev, config->offset,
			       (uint8_t *)&stored_prefix, sizeof(stored_prefix));
	if (rc != 0) {
		goto unlock;
	}

	stored_prefix = sys_le16_to_cpu(stored_prefix);

	if (stored_prefix == config->prefix_val) {
		rc = 1; /* Valid */
	} else {
		rc = 0; /* Not valid */
	}

unlock:
	retention_unlock(dev);
	return rc;
}

static int retention_read_impl(const struct device *dev, off_t offset, uint8_t *buffer,
			       size_t size)
{
	const struct retention_config *config = dev->config;
	int rc;
	off_t read_offset = config->offset;
	size_t usable_size = config->size;

	if (config->has_prefix) {
		read_offset += sizeof(uint16_t);
		usable_size -= sizeof(uint16_t);
	}

	if ((offset + size) > usable_size) {
		LOG_ERR("Read out of bounds: offset %d, size %d, usable_size %d",
			(int)offset, (int)size, (int)usable_size);
		return -EINVAL;
	}

	rc = retention_lock(dev);
	if (rc != 0) {
		return rc;
	}

	rc = retained_mem_read(config->retained_mem_dev, read_offset + offset, buffer, size);

	retention_unlock(dev);
	return rc;
}

static int retention_write_impl(const struct device *dev, off_t offset, const uint8_t *buffer,
				size_t size)
{
	const struct retention_config *config = dev->config;
	int rc;
	off_t write_offset = config->offset;
	size_t usable_size = config->size;

	if (config->has_prefix) {
		write_offset += sizeof(uint16_t);
		usable_size -= sizeof(uint16_t);
	}

	if ((offset + size) > usable_size) {
		LOG_ERR("Write out of bounds: offset %d, size %d, usable_size %d",
			(int)offset, (int)size, (int)usable_size);
		return -EINVAL;
	}

	rc = retention_lock(dev);
	if (rc != 0) {
		return rc;
	}

	rc = retained_mem_write(config->retained_mem_dev, write_offset + offset, buffer, size);
	if (rc != 0) {
		goto unlock;
	}

	if (config->has_prefix) {
		uint16_t prefix_le = sys_cpu_to_le16(config->prefix_val);
		rc = retained_mem_write(config->retained_mem_dev, config->offset,
					(uint8_t *)&prefix_le, sizeof(prefix_le));
	}

unlock:
	retention_unlock(dev);
	return rc;
}

static int retention_clear_impl(const struct device *dev)
{
	const struct retention_config *config = dev->config;
	int rc;
	size_t clear_size = config->size;
	off_t clear_offset = config->offset;

	rc = retention_lock(dev);
	if (rc != 0) {
		return rc;
	}

	rc = retained_mem_clear(config->retained_mem_dev, clear_offset, clear_size);

	retention_unlock(dev);
	return rc;
}

static const struct retention_driver_api api_funcs = {
	.size = retention_size_impl,
	.is_valid = retention_is_valid_impl,
	.read = retention_read_impl,
	.write = retention_write_impl,
	.clear = retention_clear_impl,
};

/* Public API functions */
ssize_t retention_size(const struct device *dev)
{
	const struct retention_driver_api *api = (const struct retention_driver_api *)dev->api;

	return api->size(dev);
}

int retention_is_valid(const struct device *dev)
{
	const struct retention_driver_api *api = (const struct retention_driver_api *)dev->api;

	return api->is_valid(dev);
}

int retention_read(const struct device *dev, off_t offset, uint8_t *buffer, size_t size)
{
	const struct retention_driver_api *api = (const struct retention_driver_api *)dev->api;

	return api->read(dev, offset, buffer, size);
}

int retention_write(const struct device *dev, off_t offset, const uint8_t *buffer, size_t size)
{
	const struct retention_driver_api *api = (const struct retention_driver_api *)dev->api;

	return api->write(dev, offset, buffer, size);
}

int retention_clear(const struct device *dev)
{
	const struct retention_driver_api *api = (const struct retention_driver_api *)dev->api;

	return api->clear(dev);
}

#define RETENTION_DEVICE_DEFINE(inst)                                                              \
	static struct retention_data retention_data_##inst;                                        \
	static const struct retention_config retention_config_##inst = {                           \
		.retained_mem_dev = DEVICE_DT_GET(DT_INST_PARENT(inst)),                           \
		.offset = DT_INST_REG_ADDR(inst),                                                  \
		.size = DT_INST_REG_SIZE(inst),                                                    \
		.has_prefix = DT_INST_NODE_HAS_PROP(inst, prefix),                                 \
		.prefix_val = DT_INST_PROP_OR(inst, prefix, 0),                                    \
	};                                                                                         \
	DEVICE_DT_INST_DEFINE(inst, retention_init, NULL, &retention_data_##inst,                  \
			      &retention_config_##inst, POST_KERNEL,                               \
			      CONFIG_RETENTION_INIT_PRIORITY, &api_funcs);

DT_INST_FOREACH_STATUS_OKAY(RETENTION_DEVICE_DEFINE)
